'use strict';
(()=>{
 const PRICE=100;
 const GOODS=[{key:'deadBones',name:'Kość truposza',art:'material-deadBones'},{key:'blackSteel',name:'Czarny kawałek stali',art:'material-blackSteel'},{key:'magicDust',name:'Magiczny pył',art:'material-magicDust'},{key:'rareMaterial',name:'Rzadki Materiał',art:'material-rareMaterial'},{key:'axe',name:'Topór Minotaura',art:'minotaur-axe-art'}];
 function stock(h,key){if(!GOODS.some(g=>g.key===key))throw Error('Teo nie skupuje tego przedmiotu.');if(key==='axe')return window.HeroSheet.inventory(h).filter(i=>i.kind==='minotaur-axe'&&i.slot==='weapon').length;const n=h[key]??0;if(!Number.isSafeInteger(n)||n<0)throw Error('Nieprawidłowa ilość przedmiotów.');return n;}
 function sell(h,key,quantity,id){if(!window.TaurielQuest.canEnter(h))throw Error('Najpierw ukończ zadanie Tauriel.');if(!Number.isSafeInteger(quantity)||quantity<1)throw Error('Podaj dodatnią, całkowitą liczbę sztuk.');const count=stock(h,key);if(quantity>count)throw Error('Nie masz tylu przedmiotów.');const gold=h.gold??25,total=quantity*PRICE;if(!Number.isSafeInteger(gold)||gold<0||!Number.isSafeInteger(total)||!Number.isSafeInteger(gold+total))throw Error('Nieprawidłowa ilość złota.');if(key==='axe'){const items=window.HeroSheet.inventory(h),matches=items.filter(i=>i.id===id&&i.kind==='minotaur-axe'&&i.slot==='weapon');if(quantity!==1||matches.length!==1)throw Error('Topór został sprzedany lub nie istnieje.');if(Object.values(window.HeroSheet.equipment(h)).includes(id))throw Error('Najpierw zdejmij Topór Minotaura z postaci.');return {...h,gold:gold+total,lootInventory:items.filter(i=>i.id!==id)};}return {...h,gold:gold+total,[key]:count-quantity};}
 function markup(h){const axes=window.HeroSheet.inventory(h).filter(i=>i.kind==='minotaur-axe'&&i.slot==='weapon'),worn=new Set(Object.values(window.HeroSheet.equipment(h)));return `<p class="teo-price">Cena skupu: <strong>100 złota za sztukę</strong></p><div class="teo-goods">${GOODS.map(g=>{const n=stock(h,g.key),axe=axes.find(i=>!worn.has(i.id)),blocked=g.key==='axe'&&!axe;return `<article><span class="gear-art ${g.art}" aria-hidden="true"></span><div><strong>${g.name}</strong><small>Posiadasz: ${n}${g.key==='axe'&&n&&blocked?' · Najpierw zdejmij broń':''}</small></div><label>Sztuki<input type="number" min="1" max="${g.key==='axe'?1:Math.max(1,n)}" value="1" step="1" data-teo-quantity="${g.key}" ${!n||blocked?'disabled':''}></label><button type="button" class="secondary" data-teo-sell="${g.key}" data-teo-item="${axe?.id??''}" ${!n||blocked?'disabled':''}>Sprzedaj</button></article>`}).join('')}</div>`;}
 window.TeoTrade={PRICE,GOODS,stock,sell,markup};
})();
